/**
 * session-token.ts — the config's session secret
 *
 * Browsers no longer log in with session tokens (src/auth-handler.ts: device keys), so nothing
 * issues or verifies them. `sessionSecret` stays in config.json, regenerated by setup and
 * `reauth`, because readAuthConfig() still requires it: an older connector rolled back onto the
 * same config would otherwise find it invalid.
 */

import * as crypto from 'node:crypto';

/** Generate a new 256-bit session secret (hex-encoded). */
export function generateSessionSecret(): string {
  return crypto.randomBytes(32).toString('hex');
}
